BEGIN;
DO $$ BEGIN
 ASSERT current_database() != 'yongxiang_plumb';
 IF current_database()<>'yongxiang_plumb_r39_clone' THEN RAISE EXCEPTION 'clone only'; END IF;
END $$;
CREATE TABLE IF NOT EXISTS public.annotation_run(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id text NOT NULL REFERENCES public.org(id), target_count int NOT NULL DEFAULT 200 CHECK(target_count=200), created_at timestamptz DEFAULT now());
INSERT INTO public.annotation_run(id,org_id) VALUES('47000000-0000-0000-0000-000000000001','YX') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS public.annotation_sample(run_id uuid REFERENCES public.annotation_run(id),sample_id text REFERENCES public.switchboard_gold_label(sample_id),PRIMARY KEY(run_id,sample_id),UNIQUE(sample_id));
INSERT INTO public.annotation_sample SELECT '47000000-0000-0000-0000-000000000001',sample_id FROM public.switchboard_gold_label ORDER BY sample_id LIMIT 200 ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS public.annotation_assignment(run_id uuid NOT NULL REFERENCES public.annotation_run(id),employee_id uuid NOT NULL REFERENCES public.employee(id),role text NOT NULL CHECK(role IN ('a','b','adjudicator')),order_seed text NOT NULL,PRIMARY KEY(run_id,employee_id));
CREATE UNIQUE INDEX IF NOT EXISTS annotation_one_role ON public.annotation_assignment(run_id,role) WHERE role IN ('a','b');
INSERT INTO public.annotation_assignment SELECT '47000000-0000-0000-0000-000000000001',e.id,v.role,v.seed FROM (VALUES('羅薇','a','seed-a-2026-10-27'),('吳柏頤','b','seed-b-2026-10-27'),('涂振邦','adjudicator','-'),('鍾智偉','adjudicator','-')) v(name,role,seed) JOIN public.employee e ON e.full_name=v.name AND e.org_id='YX' AND e.employment_status='active' ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS public.annotation_kappa_log(run_id uuid PRIMARY KEY REFERENCES public.annotation_run(id),kappa numeric NOT NULL,po numeric NOT NULL,pe numeric NOT NULL,n int NOT NULL,confusion jsonb NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.adjudication_queue(run_id uuid REFERENCES public.annotation_run(id),sample_id text REFERENCES public.switchboard_gold_label(sample_id),choice text CHECK(choice IN ('a','b','custom')),resolved_by uuid REFERENCES public.employee(id),resolved_at timestamptz,PRIMARY KEY(run_id,sample_id));
CREATE TABLE IF NOT EXISTS public.annotation_replay_job(run_id uuid PRIMARY KEY REFERENCES public.annotation_run(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','passed','failed')),gate_result jsonb,created_at timestamptz DEFAULT now());
CREATE OR REPLACE FUNCTION public.strip_quoted(p_text text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT regexp_replace(regexp_replace(coalesce(p_text,''),E'(?n)^>.*$','','g'),E'(?is)\\n(On [^\\n]+wrote:|在[^\\n]+寫道：|-----Original Message-----).*$', '') $$;
CREATE OR REPLACE FUNCTION public.r47_actor(p_run uuid,p_roles text[]) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE r text; BEGIN
 SELECT a.role INTO r FROM public.annotation_assignment a JOIN public.employee e ON e.id=a.employee_id JOIN public.annotation_run n ON n.id=a.run_id AND n.org_id=e.org_id WHERE a.run_id=p_run AND a.employee_id=public.current_employee_id() AND e.employment_status='active' AND e.identity_confirmed AND a.role=ANY(p_roles);
 IF r IS NULL THEN RAISE EXCEPTION 'not assigned' USING ERRCODE='42501'; END IF; RETURN r; END $$;
CREATE OR REPLACE FUNCTION public.r47_validate_label(p jsonb) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
DECLARE k text; BEGIN
 IF jsonb_typeof(p)<>'object' OR nullif(btrim(p->>'category'),'') IS NULL THEN RAISE EXCEPTION 'category required'; END IF;
 IF p->>'category' NOT IN ('CAT-01','CAT-02','CAT-03','CAT-04','CAT-05','CAT-06','CAT-07','CAT-08','CAT-09','CAT-10','noise','internal_cmd','uncertain') THEN RAISE EXCEPTION 'invalid category'; END IF;
 FOREACH k IN ARRAY ARRAY['is_noise','should_emit_card','is_internal_cmd','is_injection','is_otp','has_commitment'] LOOP IF jsonb_typeof(p->k) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'boolean required: %',k; END IF; END LOOP;
 IF (p->>'has_commitment')::bool AND (nullif(btrim(p->>'commitment_what'),'') IS NULL OR length(p->>'commitment_what')>40 OR nullif(btrim(p->>'commitment_party'),'') IS NULL OR NOT p ?& ARRAY['commitment_due','commitment_by_whom']) THEN RAISE EXCEPTION 'four commitment fields required (deadline may be null), content <=40'; END IF;
 IF nullif(p->>'commitment_due','') IS NOT NULL THEN PERFORM (p->>'commitment_due')::date; END IF;
END $$;
CREATE OR REPLACE FUNCTION public.label_next(p_run uuid) RETURNS TABLE(sample_id text,from_addr text,subject text,body text,attachments text[],received_at timestamptz,done int,total int) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE r text; seed text; BEGIN r:=public.r47_actor(p_run,ARRAY['a','b']); SELECT order_seed INTO seed FROM public.annotation_assignment WHERE run_id=p_run AND employee_id=public.current_employee_id();
 RETURN QUERY SELECT g.sample_id,m.from_addr,m.subject,public.strip_quoted(m.body_new_text),(SELECT array_agg(f.filename ORDER BY f.filename) FROM public.email_attachment f WHERE f.message_id=m.id),m.sent_at,(SELECT count(*)::int FROM public.annotation_sample s JOIN public.switchboard_gold_label x USING(sample_id) WHERE s.run_id=p_run AND CASE WHEN r='a' THEN x.label_a ELSE x.label_b END IS NOT NULL),n.target_count FROM public.annotation_sample s JOIN public.annotation_run n ON n.id=s.run_id JOIN public.switchboard_gold_label g USING(sample_id) JOIN public.email_message m ON m.message_id=g.message_id WHERE s.run_id=p_run AND CASE WHEN r='a' THEN g.label_a ELSE g.label_b END IS NULL ORDER BY md5(g.sample_id||seed),g.sample_id LIMIT 1;
END $$;
CREATE OR REPLACE FUNCTION public.compute_cohens_kappa(p_run uuid) RETURNS TABLE(po numeric,pe numeric,kappa numeric,n int,confusion jsonb) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 WITH l AS (SELECT label_a->>'category' a,label_b->>'category' b FROM public.annotation_sample s JOIN public.switchboard_gold_label g USING(sample_id) WHERE run_id=p_run AND label_a IS NOT NULL AND label_b IS NOT NULL),t AS (SELECT count(*)::int n,avg((a=b)::int)::numeric po FROM l),c AS (SELECT a cat FROM l UNION SELECT b FROM l),e AS (SELECT sum((SELECT count(*) FROM l WHERE a=c.cat)::numeric*(SELECT count(*) FROM l WHERE b=c.cat))/nullif((SELECT n::numeric*n FROM t),0) pe FROM c),f AS (SELECT a,b,count(*) n FROM l GROUP BY a,b) SELECT t.po,e.pe,CASE WHEN e.pe=1 THEN 0 ELSE (t.po-e.pe)/nullif(1-e.pe,0) END,t.n,coalesce((SELECT jsonb_agg(to_jsonb(f)) FROM f),'[]') FROM t CROSS JOIN e $$;
CREATE OR REPLACE FUNCTION public.r47_finalize(p_sample text,p jsonb,p_actor uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN
 UPDATE public.switchboard_gold_label SET gold_category=p->>'category',gold_should_filter=(p->>'is_noise')::bool,gold_should_emit_card=(p->>'should_emit_card')::bool,gold_is_internal_cmd=(p->>'is_internal_cmd')::bool,gold_is_authentic_internal_cmd=(p->>'is_internal_cmd')::bool,gold_is_injection=(p->>'is_injection')::bool,gold_is_injection_attempt=(p->>'is_injection')::bool,gold_is_otp=(p->>'is_otp')::bool,gold_is_commitment=(p->>'has_commitment')::bool,commitment_what=p->>'commitment_what',commitment_party=p->>'commitment_party',commitment_due=nullif(p->>'commitment_due','')::date,commitment_by_whom=p->>'commitment_by_whom',agreed=true,adjudicated_by_employee_id=p_actor,annotated_at=now() WHERE sample_id=p_sample AND gold_category IS NULL;
END $$;
CREATE OR REPLACE FUNCTION public.annotation_maybe_complete(p_run uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE k record; x record; o text; BEGIN
 PERFORM public.r47_actor(p_run,ARRAY['a','b','adjudicator']); PERFORM 1 FROM public.annotation_run WHERE id=p_run FOR UPDATE;
 IF (SELECT count(*) FROM public.annotation_sample WHERE run_id=p_run)<>200 OR EXISTS(SELECT 1 FROM public.annotation_sample s JOIN public.switchboard_gold_label g USING(sample_id) WHERE run_id=p_run AND (label_a IS NULL OR label_b IS NULL)) THEN RETURN; END IF;
 SELECT * INTO k FROM public.compute_cohens_kappa(p_run); SELECT org_id INTO o FROM public.annotation_run WHERE id=p_run;
 INSERT INTO public.annotation_kappa_log VALUES(p_run,k.kappa,k.po,k.pe,k.n,k.confusion,now()) ON CONFLICT DO NOTHING;
 IF k.kappa<0.75 THEN
 PERFORM public.enqueue_card(o,NULL,a.employee_id,'admin','kappa-low:'||p_run||':'||a.employee_id,jsonb_build_array(jsonb_build_object('label','兩人一致率 κ','value',k.kappa,'sql_id','gold.kappa')),jsonb_build_object('label','一致率不足，先對齊標註指南再重新建立盲標批次','top_confusions',k.confusion)) FROM public.annotation_assignment a WHERE a.run_id=p_run AND role='adjudicator'; RETURN; END IF;
 INSERT INTO public.adjudication_queue(run_id,sample_id) SELECT p_run,g.sample_id FROM public.annotation_sample s JOIN public.switchboard_gold_label g USING(sample_id) WHERE s.run_id=p_run AND (label_a-ARRAY['by','at']) IS DISTINCT FROM (label_b-ARRAY['by','at']) ON CONFLICT DO NOTHING;
 FOR x IN SELECT g.* FROM public.annotation_sample s JOIN public.switchboard_gold_label g USING(sample_id) WHERE s.run_id=p_run AND NOT EXISTS(SELECT 1 FROM public.adjudication_queue q WHERE q.run_id=p_run AND q.sample_id=g.sample_id) LOOP PERFORM public.r47_finalize(x.sample_id,x.label_a); END LOOP;
 IF NOT EXISTS(SELECT 1 FROM public.annotation_sample s JOIN public.switchboard_gold_label g USING(sample_id) WHERE run_id=p_run AND gold_category IS NULL) THEN INSERT INTO public.annotation_replay_job(run_id) VALUES(p_run) ON CONFLICT DO NOTHING; END IF;
END $$;
CREATE OR REPLACE FUNCTION public.label_submit(p_run uuid,p_sample text,p_label jsonb) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE r text; BEGIN r:=public.r47_actor(p_run,ARRAY['a','b']); PERFORM 1 FROM public.annotation_run WHERE id=p_run FOR UPDATE; PERFORM public.r47_validate_label(p_label);
 IF NOT EXISTS(SELECT 1 FROM public.annotation_sample WHERE run_id=p_run AND sample_id=p_sample) THEN RAISE EXCEPTION 'unknown sample'; END IF;
 p_label:=p_label||jsonb_build_object('by',public.current_employee_id(),'at',now());
 UPDATE public.switchboard_gold_label SET label_a=CASE WHEN r='a' THEN p_label ELSE label_a END,label_b=CASE WHEN r='b' THEN p_label ELSE label_b END WHERE sample_id=p_sample AND CASE WHEN r='a' THEN label_a ELSE label_b END IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'already labeled'; END IF; PERFORM public.annotation_maybe_complete(p_run); RETURN 1; END $$;
CREATE OR REPLACE FUNCTION public.adjudicate_next(p_run uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE x jsonb; BEGIN PERFORM public.r47_actor(p_run,ARRAY['adjudicator']); IF NOT EXISTS(SELECT 1 FROM public.annotation_kappa_log WHERE run_id=p_run AND n=200 AND kappa>=0.75) THEN RETURN jsonb_build_object('status','尚未完成'); END IF;
 SELECT jsonb_build_object('sample_id',g.sample_id,'from_addr',m.from_addr,'subject',m.subject,'body',public.strip_quoted(m.body_new_text),'a',g.label_a-ARRAY['by','at'],'b',g.label_b-ARRAY['by','at']) INTO x FROM public.adjudication_queue q JOIN public.switchboard_gold_label g USING(sample_id) JOIN public.email_message m ON m.message_id=g.message_id WHERE q.run_id=p_run AND q.resolved_at IS NULL ORDER BY g.sample_id LIMIT 1; RETURN coalesce(x,'{"status":"完成"}'); END $$;
CREATE OR REPLACE FUNCTION public.adjudicate_submit(p_run uuid,p_sample text,p_choice text,p_custom jsonb DEFAULT NULL) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE p jsonb; BEGIN
 PERFORM public.r47_actor(p_run,ARRAY['adjudicator']); PERFORM 1 FROM public.annotation_run WHERE id=p_run FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.annotation_kappa_log WHERE run_id=p_run AND n=200 AND kappa>=0.75) THEN RAISE EXCEPTION '尚未完成'; END IF;
 IF p_choice NOT IN ('a','b','custom') OR p_choice IS NULL THEN RAISE EXCEPTION 'invalid choice'; END IF;
 UPDATE public.adjudication_queue SET choice=p_choice,resolved_by=public.current_employee_id(),resolved_at=now() WHERE run_id=p_run AND sample_id=p_sample AND resolved_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'not pending'; END IF;
 SELECT CASE p_choice WHEN 'a' THEN label_a WHEN 'b' THEN label_b ELSE p_custom END INTO p FROM public.switchboard_gold_label WHERE sample_id=p_sample; PERFORM public.r47_validate_label(p); PERFORM public.r47_finalize(p_sample,p,public.current_employee_id()); PERFORM public.annotation_maybe_complete(p_run); RETURN 1; END $$;
-- Structural walls: table-level grants must also go; a column REVOKE alone is insufficient.
REVOKE ALL ON public.switchboard_gold_label FROM PUBLIC,plumb_app;
REVOKE SELECT(label_a,label_b) ON public.switchboard_gold_label FROM plumb_app;
CREATE TABLE IF NOT EXISTS public.deep_link_open_log(id bigserial PRIMARY KEY,card_id uuid,case_id uuid,rcpt_open_id text,opener_employee_id uuid,outcome text NOT NULL CHECK(outcome IN ('direct','stale','other_viewer','no_access','invalid')),opened_at timestamptz DEFAULT now(),assignee_at_open uuid);
CREATE OR REPLACE FUNCTION public.resolve_deep_link_open(p_card_id uuid,p_case_id uuid,p_rcpt_open_id text,p_opener_employee_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE c public.card; e public.employee; outcome text; BEGIN
 IF p_opener_employee_id IS DISTINCT FROM public.current_employee_id() THEN RAISE EXCEPTION 'session identity mismatch' USING ERRCODE='42501'; END IF;
 SELECT * INTO e FROM public.employee WHERE id=p_opener_employee_id AND employment_status='active' AND identity_confirmed;
 IF NOT FOUND THEN RAISE EXCEPTION 'inactive identity' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.card WHERE id=p_card_id AND case_id=p_case_id AND org_id=e.org_id FOR SHARE;
 IF c.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.session_list_for(e.id,false) s WHERE s.case_id=p_case_id) THEN outcome:='no_access';
 ELSIF e.lark_open_id IS DISTINCT FROM p_rcpt_open_id THEN outcome:='other_viewer';
 ELSIF c.assignee_employee_id=e.id AND c.state IN ('open','escalated','dry_run') THEN outcome:='direct'; ELSE outcome:='stale'; END IF;
 INSERT INTO public.deep_link_open_log(card_id,case_id,rcpt_open_id,opener_employee_id,outcome,assignee_at_open) VALUES(p_card_id,p_case_id,p_rcpt_open_id,e.id,outcome,c.assignee_employee_id); RETURN outcome; END $$;
INSERT INTO public.guard_pattern(name,kind,py_regex,pg_regex,flags,source_sha) VALUES
('r47_lark_currency','lark_notice','(?:NT\\$|TWD|USD|[$＄￥¥€])\\s*[0-9]|[0-9][0-9,.]*\\s*(?:元|萬元|圓)','(?i)(NT\$|TWD|USD|[$＄￥¥€])[[:space:]]*[0-9]|[0-9][0-9,.]*[[:space:]]*(元|萬元|圓)','i','r47'),
('r47_lark_serial','lark_notice','業主往來\\s*[0-9]+','業主往來[[:space:]]*[0-9]+','','r47'),
('r47_lark_otp','lark_notice','[0-9]{6}','[0-9]{6}','','r47') ON CONFLICT(name) DO UPDATE SET pg_regex=excluded.pg_regex,py_regex=excluded.py_regex;
CREATE OR REPLACE FUNCTION public.r47_notice_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$ BEGIN IF NEW.channel='lark' AND (length(NEW.payload->>'text')>40 OR NOT NEW.payload ?& ARRAY['text','link','card_id'] OR NEW.payload-ARRAY['text','link','card_id']<>'{}'::jsonb) THEN RAISE EXCEPTION 'doorbell must be one short title and a link'; END IF; IF NEW.channel='lark' AND public.guard_hit('lark_notice',coalesce(NEW.payload->>'text','')) IS NOT NULL THEN RAISE EXCEPTION 'unsafe lark doorbell'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS r47_notice_guard ON public.notification_outbox;
CREATE TRIGGER r47_notice_guard BEFORE INSERT OR UPDATE ON public.notification_outbox FOR EACH ROW EXECUTE FUNCTION public.r47_notice_guard();
CREATE TABLE IF NOT EXISTS public.org_mode(org_id text PRIMARY KEY REFERENCES public.org(id),mode text NOT NULL DEFAULT 'shadow' CHECK(mode IN ('shadow','live')),set_by uuid NOT NULL REFERENCES public.employee(id),reason text NOT NULL,set_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.org_mode_log(id bigserial PRIMARY KEY,org_id text NOT NULL REFERENCES public.org(id),mode text NOT NULL CHECK(mode IN ('shadow','live')),set_by uuid NOT NULL REFERENCES public.employee(id),reason text NOT NULL,set_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.org_mode SELECT o.id,'shadow',e.id,'Tuesday 08:30 Day-1 starts in Shadow Mode',now() FROM public.org o CROSS JOIN LATERAL(SELECT id FROM public.employee WHERE role_code='gm' AND employment_status='active' ORDER BY id LIMIT 1)e ON CONFLICT DO NOTHING;
INSERT INTO public.org_mode_log(org_id,mode,set_by,reason,set_at) SELECT m.* FROM public.org_mode m WHERE NOT EXISTS(SELECT 1 FROM public.org_mode_log l WHERE l.org_id=m.org_id);
DO $$ BEGIN IF to_regprocedure('public.r47_org_live_ready_base(text)') IS NULL THEN ALTER FUNCTION public.org_live_ready(text) RENAME TO r47_org_live_ready_base; END IF; END $$;
CREATE OR REPLACE FUNCTION public.org_live_ready(p_org text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT b || jsonb_build_object('mode',coalesce(m.mode,CASE WHEN p_org LIKE 'R29-%' THEN 'live' ELSE 'shadow' END),'ready',coalesce((b->>'ready')::bool,false) AND coalesce(m.mode,CASE WHEN p_org LIKE 'R29-%' THEN 'live' ELSE 'shadow' END)='live','badge',p_org||CASE WHEN coalesce(m.mode,CASE WHEN p_org LIKE 'R29-%' THEN 'live' ELSE 'shadow' END)='live' AND (b->>'ready')::bool THEN ' 已上線' ELSE ' 試運轉' END) FROM (SELECT public.r47_org_live_ready_base(p_org) b)x LEFT JOIN public.org_mode m ON m.org_id=p_org $$;
CREATE OR REPLACE FUNCTION public.org_kill_switch(p_org text,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE me uuid:=public.current_employee_id(); n int; admin_id uuid; BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.employee WHERE id=me AND org_id=p_org AND employment_status='active' AND identity_confirmed AND role_code IN ('gm','it')) THEN RAISE EXCEPTION 'gm/it only' USING ERRCODE='42501'; END IF;
 IF p_reason IS NULL OR length(btrim(p_reason))<6 THEN RAISE EXCEPTION 'reason required (6 characters)'; END IF;
 INSERT INTO public.org_mode VALUES(p_org,'shadow',me,p_reason,now()) ON CONFLICT(org_id) DO UPDATE SET mode='shadow',set_by=me,reason=p_reason,set_at=now();
 INSERT INTO public.org_mode_log(org_id,mode,set_by,reason,set_at) SELECT * FROM public.org_mode WHERE org_id=p_org;
 UPDATE public.outbound_message SET delivery_status='HELD_BY_KILL_SWITCH' WHERE org_id=p_org AND delivery_status IN ('approved','sending'); GET DIAGNOSTICS n=ROW_COUNT;
 SELECT id INTO admin_id FROM public.employee WHERE org_id=p_org AND role_code='admin' AND employment_status='active' AND identity_confirmed ORDER BY id LIMIT 1;
 IF admin_id IS NULL THEN RAISE EXCEPTION 'active admin required'; END IF;
 PERFORM public.enqueue_card(p_org,NULL,admin_id,'admin','kill-switch:'||gen_random_uuid(),jsonb_build_array(jsonb_build_object('label','暫停時已核准未寄出','value',n,'sql_id','outbound.held_count')),jsonb_build_object('label','已切回試運轉：請改為手寄，系統草稿仍可參考','reason',p_reason)); END $$;
INSERT INTO public.evidence_sql VALUES('gold.kappa','雙人盲標一致率','SELECT kappa FROM annotation_kappa_log ORDER BY created_at DESC LIMIT 1','numeric'),('outbound.held_count','暫停未寄出','SELECT count(*) FROM outbound_message WHERE org_id=:org_id AND delivery_status=''HELD_BY_KILL_SWITCH''','int') ON CONFLICT(sql_id) DO NOTHING;
DO $$ BEGIN IF to_regprocedure('public.r47_backtest_gate_base(uuid)') IS NULL THEN ALTER FUNCTION public.backtest_gate(uuid) RENAME TO r47_backtest_gate_base; END IF; END $$;
CREATE OR REPLACE FUNCTION public.backtest_gate(p_run_id uuid) RETURNS TABLE(metric text,pass boolean,actual text,required text) LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.annotation_run WHERE id=p_run_id) THEN
  IF (SELECT count(*) FROM public.annotation_sample s JOIN public.switchboard_gold_label g USING(sample_id) WHERE s.run_id=p_run_id AND g.gold_category IS NOT NULL AND g.label_a IS NOT NULL AND g.label_b IS NOT NULL)<>200 OR (SELECT count(*) FROM public.switchboard_backtest_eval WHERE run_id=p_run_id)<>200 THEN RETURN QUERY SELECT 'BACKTEST-200'::text,false,'NOT_RUN: run requires 200 finalized samples and 200 evaluations'::text,'200'::text; RETURN; END IF;
  RETURN QUERY SELECT b.metric,CASE WHEN b.metric='COHEN_KAPPA_200' THEN (SELECT k.n=200 AND k.kappa>=0.75 FROM public.annotation_kappa_log k WHERE k.run_id=p_run_id) ELSE b.pass END,CASE WHEN b.metric='COHEN_KAPPA_200' THEN (SELECT 'run kappa='||k.kappa FROM public.annotation_kappa_log k WHERE k.run_id=p_run_id) ELSE b.actual END,b.required FROM public.r47_backtest_gate_base(p_run_id) b;
 ELSE RETURN QUERY SELECT * FROM public.r47_backtest_gate_base(p_run_id); END IF; END $$;
-- Observations must come from the Sheet connector; absence is unknown/red, never guessed.
CREATE TABLE IF NOT EXISTS public.r47_sheet_observation(org_id text PRIMARY KEY REFERENCES public.org(id),max_serial int NOT NULL,observed_at timestamptz NOT NULL,writeback_pending_since timestamptz,source_ref text NOT NULL);
CREATE TABLE IF NOT EXISTS public.r47_live_rehearsal(org_id text PRIMARY KEY REFERENCES public.org(id),passed_at timestamptz NOT NULL,evidence_ref text NOT NULL,sender_function_hash text NOT NULL);
CREATE OR REPLACE FUNCTION public.r47_work_hours(p_start timestamptz,p_end timestamptz) RETURNS numeric LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT coalesce(sum(greatest(0,extract(epoch FROM(least(p_end,b.finish)-greatest(p_start,b.start)))))/3600,0)
 FROM generate_series((p_start AT TIME ZONE 'Asia/Taipei')::date,(p_end AT TIME ZONE 'Asia/Taipei')::date,interval '1 day') d
 CROSS JOIN LATERAL (VALUES((d::date+time '08:30') AT TIME ZONE 'Asia/Taipei',(d::date+time '12:00') AT TIME ZONE 'Asia/Taipei'),((d::date+time '13:00') AT TIME ZONE 'Asia/Taipei',(d::date+time '17:00') AT TIME ZONE 'Asia/Taipei')) b(start,finish)
 WHERE extract(isodow FROM d)<6 $$;
CREATE OR REPLACE FUNCTION public.r47_health_values(p_org text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
 SELECT jsonb_build_object(
 'intake.today_count',(SELECT count(*) FROM public.email_message WHERE org_id=p_org AND (ingested_at AT TIME ZONE 'Asia/Taipei')::date=(now() AT TIME ZONE 'Asia/Taipei')::date),
 'card.touched_count',(SELECT count(*) FROM public.email_message m WHERE m.org_id=p_org AND (m.ingested_at AT TIME ZONE 'Asia/Taipei')::date=(now() AT TIME ZONE 'Asia/Taipei')::date AND EXISTS(SELECT 1 FROM public.card c WHERE c.org_id=p_org AND c.case_id=m.case_id AND c.acted_at>=m.ingested_at)),
 'card.untouched_oldest_hours',coalesce((SELECT max(public.r47_work_hours(m.ingested_at,now())) FROM public.email_message m WHERE m.org_id=p_org AND (m.ingested_at AT TIME ZONE 'Asia/Taipei')::date=(now() AT TIME ZONE 'Asia/Taipei')::date AND NOT EXISTS(SELECT 1 FROM public.card c WHERE c.org_id=p_org AND c.case_id=m.case_id AND c.acted_at>=m.ingested_at)),0),
 'quarantine.pending',(SELECT count(*) FROM public.email_message WHERE org_id=p_org AND quarantine_reason IS NOT NULL),
 'outbound.today_sent',(SELECT count(*) FROM public.outbound_message WHERE org_id=p_org AND (sent_at AT TIME ZONE 'Asia/Taipei')::date=(now() AT TIME ZONE 'Asia/Taipei')::date),
 'outbound.approved',(SELECT count(*) FROM public.outbound_message WHERE org_id=p_org AND delivery_status IN ('approved','HELD_BY_KILL_SWITCH')),
 'sent_copy.verified',(SELECT count(*) FROM public.outbound_message o JOIN public.email_message m ON m.message_id=o.sent_message_id WHERE o.org_id=p_org AND m.org_id=p_org AND m.sent_copy_verified AND (o.sent_at AT TIME ZONE 'Asia/Taipei')::date=(now() AT TIME ZONE 'Asia/Taipei')::date),
 'sent_copy.overdue',(SELECT count(*) FROM public.outbound_message o WHERE org_id=p_org AND sent_at<now()-interval '15 minutes' AND NOT EXISTS(SELECT 1 FROM public.email_message m WHERE m.org_id=p_org AND m.message_id=o.sent_message_id AND m.sent_copy_verified)),
 'outbound.failed',(SELECT count(*) FROM public.outbound_message WHERE org_id=p_org AND delivery_status IN ('send_failed','failed')),
 'sheet_mirror.max_serial',(SELECT max_serial FROM public.r47_sheet_observation WHERE org_id=p_org),
 'serial_allocator.latest',(SELECT next_serial-1 FROM public.serial_allocator WHERE org_id=p_org),
 'sheet.fresh',EXISTS(SELECT 1 FROM public.r47_sheet_observation WHERE org_id=p_org AND observed_at>now()-interval '10 minutes' AND (writeback_pending_since IS NULL OR writeback_pending_since>now()-interval '10 minutes')))
$$;
INSERT INTO public.evidence_sql(sql_id,description,sql_text,returns) SELECT k,k,'SELECT (r47_health_values(:org_id)->>'||quote_literal(k)||')::'||CASE WHEN k='sheet.fresh' THEN 'boolean' ELSE 'numeric' END,CASE WHEN k='sheet.fresh' THEN 'bool' ELSE 'numeric' END FROM unnest(ARRAY['intake.today_count','card.touched_count','card.untouched_oldest_hours','quarantine.pending','outbound.today_sent','outbound.approved','sent_copy.verified','sent_copy.overdue','outbound.failed','sheet_mirror.max_serial','serial_allocator.latest','sheet.fresh'])k ON CONFLICT(sql_id) DO UPDATE SET sql_text=excluded.sql_text;
CREATE OR REPLACE FUNCTION public.day1_health_panel(p_org text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE v jsonb; m public.org_mode; bt bool; offboard bool; gates bool; sh bool; BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.employee WHERE id=public.current_employee_id() AND org_id=p_org AND employment_status='active' AND identity_confirmed) THEN RAISE EXCEPTION 'org access denied' USING ERRCODE='42501'; END IF;
 v:=public.r47_health_values(p_org); SELECT * INTO m FROM public.org_mode WHERE org_id=p_org;
 SELECT EXISTS(SELECT 1 FROM public.annotation_run r JOIN public.annotation_kappa_log k ON k.run_id=r.id JOIN public.annotation_replay_job j ON j.run_id=r.id WHERE r.org_id=p_org AND k.n=200 AND k.kappa>=0.75 AND j.status='passed' AND NOT EXISTS(SELECT 1 FROM public.backtest_gate(r.id) WHERE NOT pass)) INTO bt;
 SELECT NOT EXISTS(SELECT 1 FROM public.card c JOIN public.employee e ON e.id=c.assignee_employee_id WHERE c.org_id=p_org AND c.state IN ('open','escalated','dry_run') AND (e.employment_status<>'active' OR e.full_name LIKE '%前行政%')) AND NOT EXISTS(SELECT 1 FROM public.employee e JOIN public.employee_role_map rm ON rm.employee_id=e.id WHERE e.org_id=p_org AND e.employment_status='active' AND e.full_name LIKE '%前行政%') INTO offboard;
 -- Without executed isolation verification evidence, do not green-light production.
 SELECT EXISTS(SELECT 1 FROM public.r45_verification_evidence WHERE code='SW-SEND-03' AND verified_at>now()-interval '24 hours' AND schema_fingerprint=public.r45_send_schema_fingerprint()) AND NOT EXISTS(SELECT 1 FROM public.email_message WHERE org_id=p_org AND quarantine_reason IS NOT NULL) INTO gates;
 sh:=coalesce((v->>'sheet.fresh')::bool,false) AND v->>'sheet_mirror.max_serial'=v->>'serial_allocator.latest';
 RETURN jsonb_build_object('org',p_org,'mode',coalesce(m.mode,'shadow'),'badge',p_org||CASE WHEN m.mode='live' THEN ' 已上線' ELSE ' 試運轉' END,'prerequisites',jsonb_build_array(jsonb_build_object('label','200 封回測與雙人盲標 κ≥0.75','pass',bt),jsonb_build_object('label','離職交接清零','pass',offboard),jsonb_build_object('label','收發隔離閘門全綠','pass',gates),jsonb_build_object('label','紀錄表雙向同步正常','pass',sh)),
 'indicators',jsonb_build_array(jsonb_build_object('label','進件接手','text',format('今天進來 %s 封，%s 封已有人接，%s 封沒人動（最久 %s 小時）',v->>'intake.today_count',v->>'card.touched_count',(v->>'intake.today_count')::int-(v->>'card.touched_count')::int,v->>'card.untouched_oldest_hours'),'red',(v->>'card.untouched_oldest_hours')::numeric>4 OR (v->>'quarantine.pending')::int>5,'sql_ids',ARRAY['intake.today_count','card.touched_count','card.untouched_oldest_hours','quarantine.pending'],'href','/api/r47/evidence?indicator=intake'),
 jsonb_build_object('label','寄出與回執','text',CASE WHEN m.mode='live' THEN format('今天寄出 %s 封，%s 封已在寄件備份確認，%s 封寄不出去',v->>'outbound.today_sent',v->>'sent_copy.verified',v->>'outbound.failed') ELSE format('今天要寄 %s 封：試運轉中，由羅薇手寄；系統草稿 %s 封已核准',v->>'outbound.approved',v->>'outbound.approved') END,'red',(v->>'sent_copy.overdue')::int>0 OR (v->>'outbound.failed')::int>0,'sql_ids',ARRAY['outbound.today_sent','sent_copy.verified','outbound.failed','outbound.approved','sent_copy.overdue'],'href','/api/r47/evidence?indicator=outbound'),
 jsonb_build_object('label','紀錄表對帳','text',format('紀錄表最新一號 %s = 系統最新一號 %s',coalesce(v->>'sheet_mirror.max_serial','尚未取得'),coalesce(v->>'serial_allocator.latest','尚未取得')),'red',NOT coalesce(sh,false),'sql_ids',ARRAY['sheet_mirror.max_serial','serial_allocator.latest','sheet.fresh'],'href','/api/r47/evidence?indicator=sheet')),'evidence',v,'kill_switch',jsonb_build_object('active',coalesce(m.mode,'shadow')='shadow','reason',m.reason,'set_by',m.set_by,'set_at',m.set_at),'can_kill_switch',EXISTS(SELECT 1 FROM public.employee WHERE id=public.current_employee_id() AND role_code IN ('gm','it')),'is_gm',EXISTS(SELECT 1 FROM public.employee WHERE id=public.current_employee_id() AND role_code='gm'),'can_go_live',coalesce((public.r47_org_live_ready_base(p_org)->>'ready')::bool,false) AND bt AND offboard AND gates AND sh AND EXISTS(SELECT 1 FROM public.r47_live_rehearsal WHERE org_id=p_org AND sender_function_hash=md5(pg_get_functiondef('public.outbound_send_live(uuid,uuid)'::regprocedure))));
END $$;
CREATE OR REPLACE FUNCTION public.org_go_live(p_org text,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE panel jsonb; BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.employee WHERE id=public.current_employee_id() AND org_id=p_org AND role_code='gm' AND employment_status='active' AND identity_confirmed) THEN RAISE EXCEPTION 'gm only' USING ERRCODE='42501'; END IF;
 IF p_reason IS NULL OR length(btrim(p_reason))<6 THEN RAISE EXCEPTION 'reason required'; END IF;
 PERFORM 1 FROM public.org_mode WHERE org_id=p_org FOR UPDATE; panel:=public.day1_health_panel(p_org);
 IF NOT coalesce((panel->>'can_go_live')::bool,false) THEN RAISE EXCEPTION 'pre-launch prerequisites or live-send rehearsal missing'; END IF;
 UPDATE public.org_mode SET mode='live',set_by=public.current_employee_id(),reason=p_reason,set_at=now() WHERE org_id=p_org; INSERT INTO public.org_mode_log(org_id,mode,set_by,reason,set_at) SELECT * FROM public.org_mode WHERE org_id=p_org; END $$;
CREATE OR REPLACE FUNCTION public.r47_gold_lock() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$ BEGIN
 IF OLD.gold_category IS NOT NULL AND (to_jsonb(NEW)-ARRAY['note']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['note']) AND NOT EXISTS(SELECT 1 FROM public.employee WHERE id=public.current_employee_id() AND role_code='gm' AND employment_status='active') THEN RAISE EXCEPTION 'gold finalized: gm only' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS r47_gold_lock ON public.switchboard_gold_label;
CREATE TRIGGER r47_gold_lock BEFORE UPDATE ON public.switchboard_gold_label FOR EACH ROW EXECUTE FUNCTION public.r47_gold_lock();
CREATE OR REPLACE FUNCTION public.r47_assert_all() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
BEGIN
 ASSERT current_database() != 'yongxiang_plumb';
 IF EXISTS(SELECT 1 FROM public.deep_link_open_log WHERE outcome='direct' AND opener_employee_id IS DISTINCT FROM assignee_at_open) THEN RAISE EXCEPTION 'SW-LINK-01'; END IF;
 IF public.guard_hit('lark_notice','NT$ 10,000') IS NULL OR public.guard_hit('lark_notice','業主往來12091') IS NULL OR public.guard_hit('lark_notice','OTP 123456') IS NULL OR public.guard_hit('lark_notice','來信詢問報價修正 · 球在你手上') IS NOT NULL OR EXISTS(SELECT 1 FROM public.notification_outbox WHERE channel='lark' AND public.guard_hit('lark_notice',payload->>'text') IS NOT NULL) THEN RAISE EXCEPTION 'SW-LINK-02'; END IF;
 IF has_table_privilege('plumb_app','public.switchboard_gold_label','SELECT') OR has_column_privilege('plumb_app','public.switchboard_gold_label','label_a','SELECT') OR has_column_privilege('plumb_app','public.switchboard_gold_label','label_b','SELECT') THEN RAISE EXCEPTION 'SW-LABEL-01 blind wall'; END IF;
 IF (SELECT count(*) FROM public.annotation_assignment WHERE run_id='47000000-0000-0000-0000-000000000001')<>4 THEN RAISE EXCEPTION 'SW-LABEL-02 assignments'; END IF;
 IF EXISTS(SELECT 1 FROM public.employee e WHERE full_name LIKE '%前行政%' AND employment_status='active') OR EXISTS(SELECT 1 FROM public.annotation_assignment a JOIN public.employee e ON e.id=a.employee_id WHERE e.full_name LIKE '%前行政%') THEN RAISE EXCEPTION 'SW-ROSTER-47'; END IF;
 IF EXISTS(SELECT 1 FROM public.org_mode WHERE mode='shadow' AND (public.org_live_ready(org_id)->>'ready')::bool) THEN RAISE EXCEPTION 'SW-KILL-01'; END IF;
 RETURN jsonb_build_object('SW-LABEL-01','PASS','SW-LABEL-02','PASS','SW-LINK-01','PASS','SW-LINK-02','PASS','SW-KILL-01','PASS','SW-ROSTER-47','PASS'); END $$;
DO $integration$ DECLARE ddl text; BEGIN SELECT pg_get_functiondef('public.r32_assert_all()'::regprocedure) INTO ddl; IF position('public.r47_assert_all()' IN ddl)=0 THEN IF position('|| public.r46_assert_all();' IN ddl)>0 THEN EXECUTE replace(ddl,'|| public.r46_assert_all();','|| public.r46_assert_all() || public.r47_assert_all();'); ELSIF position('''BACKTEST-200'', v_bt_status);' IN ddl)>0 THEN EXECUTE replace(ddl,'''BACKTEST-200'', v_bt_status);','''BACKTEST-200'', v_bt_status) || public.r47_assert_all();'); ELSIF position('r48_r32_assert_all_base()' IN ddl)>0 THEN EXECUTE 'CREATE OR REPLACE FUNCTION public.r32_assert_all() RETURNS jsonb LANGUAGE sql AS $f$ SELECT public.r48_r32_assert_all_base() || public.r47_assert_all() || public.r48_assert_all() $f$'; END IF; END IF; END $integration$;
REVOKE ALL ON public.annotation_run,public.annotation_sample,public.annotation_assignment,public.annotation_kappa_log,public.adjudication_queue,public.annotation_replay_job,public.deep_link_open_log,public.org_mode,public.org_mode_log,public.r47_sheet_observation,public.r47_live_rehearsal FROM PUBLIC,plumb_app;
REVOKE ALL ON FUNCTION public.r47_actor(uuid,text[]),public.r47_finalize(text,jsonb,uuid),public.compute_cohens_kappa(uuid),public.r47_health_values(text),public.r47_org_live_ready_base(text) FROM PUBLIC,plumb_app;
DO $$ DECLARE p record; BEGIN FOR p IN SELECT oid::regprocedure sig FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('label_next','label_submit','adjudicate_next','adjudicate_submit','annotation_maybe_complete','resolve_deep_link_open','org_kill_switch','org_go_live','day1_health_panel','r47_assert_all','org_live_ready') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',p.sig); EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO plumb_app',p.sig); END LOOP; END $$;
INSERT INTO public.schema_migration(name,checksum,applied_at) VALUES('009d8_r47_blind_label_deeplink_killswitch',current_setting('app.migration_sha',true),now()) ON CONFLICT(name) DO UPDATE SET checksum=excluded.checksum,applied_at=excluded.applied_at;
COMMIT;
